	function atfa_expo27_css() {
		return <<<'ATFA_EXPO27_CSS'
/* ATFA Expo 2027 Hall 5 floor plan, v3.4.0.
   Every rule is scoped to #atfa-expo27 (the plan) or #atfa-expo27-modal (the popup),
   so the theme and Elementor can't restyle the buttons, headings or links inside. */

#atfa-expo27,
#atfa-expo27-modal {
  --brand: #A8600C;
  --brand-dk: #8A4E09;
  --brand-lt: #FDF2E4;
  --timber: #F79320;
  --ink: #16211C;
  --muted: #5F6B66;
  --line: #DDE3E0;
  --paper: #fff;
  --bg: #F7F9F8;
  --avail: #2E7D4F;
  --hold: #D99A21;
  --sold: #96A29C;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  text-align: left;
  letter-spacing: normal;
  word-spacing: normal;
  -webkit-text-size-adjust: 100%;
}

#atfa-expo27 *, #atfa-expo27 *::before, #atfa-expo27 *::after,
#atfa-expo27-modal *, #atfa-expo27-modal *::before, #atfa-expo27-modal *::after {
  box-sizing: border-box;
}

/* Neutralise theme styles on the elements we use */
#atfa-expo27 h1, #atfa-expo27 h2, #atfa-expo27 h3,
#atfa-expo27-modal h2 {
  margin: 0; padding: 0; border: 0; background: none;
  font-family: inherit; text-transform: none; letter-spacing: normal; line-height: 1.2;
}
#atfa-expo27 p, #atfa-expo27-modal p, #atfa-expo27 dl, #atfa-expo27 dt, #atfa-expo27 dd { margin: 0; padding: 0; }
#atfa-expo27 ul, #atfa-expo27 li { margin: 0; padding: 0; list-style: none; }
#atfa-expo27 li::before, #atfa-expo27 li::marker { content: none; }
#atfa-expo27 button, #atfa-expo27 input,
#atfa-expo27-modal button {
  font-family: inherit; text-transform: none; letter-spacing: normal; text-shadow: none;
  box-shadow: none; margin: 0; min-height: 0; min-width: 0; width: auto; height: auto;
  -webkit-appearance: none; appearance: none;
}
#atfa-expo27 a, #atfa-expo27-modal a { text-decoration: none; box-shadow: none; text-transform: none; }
#atfa-expo27 svg { overflow: hidden; }

/* Layout */
#atfa-expo27 .afpx-wrap {
  container-type: inline-size;
  container-name: afpx;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  max-width: 1400px;
  margin: 0 auto;
}

/* Staff bar: only printed for logged-in staff, never for visitors */
#atfa-expo27 .afpx-staff {
  max-width: 1400px; margin: 0 auto 10px;
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px;
  padding: 10px 12px 10px 14px;
  border: 1px dashed var(--hold); border-radius: 12px;
  background: #FFF8EC; color: #4A3D24;
  font-size: 13px; line-height: 1.45;
}
#atfa-expo27 .afpx-staff-tag {
  flex: none; padding: 3px 9px; border-radius: 999px;
  background: #F6DFAE; color: #6B4B12;
  font-size: 10.5px; font-weight: 700; line-height: 1.4; letter-spacing: .7px; text-transform: uppercase;
}
#atfa-expo27 .afpx-staff-text { flex: 1 1 280px; min-width: 0; font-size: 13px; }
#atfa-expo27 .afpx-staff-status { font-weight: 600; color: #3A3020; }
#atfa-expo27 .afpx-staff-status.is-warn { color: #9A3412; }
#atfa-expo27 .afpx-staff-note { color: #6F6250; }
#atfa-expo27 .afpx-staff-btns { flex: none; display: flex; flex-wrap: wrap; gap: 8px; }
#atfa-expo27 .afpx-staff .afpx-btn.is-small { min-height: 34px; white-space: nowrap; }

#atfa-expo27 .afpx-top {
  background: #141618;
  color: #fff;
  padding: 18px 22px;
  display: flex;
  flex-wrap: wrap;
  gap: 14px 24px;
  align-items: center;
  justify-content: space-between;
  border-bottom: 3px solid var(--timber);
}
#atfa-expo27 .afpx-top h1 { color: #fff; font-size: 21px; font-weight: 700; }
#atfa-expo27 .afpx-top p { color: #F3D9BB; font-size: 13px; margin-top: 4px; max-width: 760px; }

#atfa-expo27 .afpx-stats { display: flex; gap: 22px; }
#atfa-expo27 .afpx-stats div { display: flex; flex-direction: column-reverse; align-items: flex-end; }
#atfa-expo27 .afpx-stats dd { color: #fff; font-size: 22px; font-weight: 700; line-height: 1.1; }
#atfa-expo27 .afpx-stats dt { color: #F3D9BB; font-size: 10.5px; text-transform: uppercase; letter-spacing: .7px; }

#atfa-expo27 .afpx-body { display: grid; grid-template-columns: minmax(0, 1fr) 330px; }
#atfa-expo27 .afpx-mapcol { background: var(--paper); min-width: 0; display: flex; flex-direction: column; }

/* Toolbar */
#atfa-expo27 .afpx-toolbar {
  display: flex; flex-wrap: wrap; gap: 8px; align-items: center;
  padding: 10px 14px; border-bottom: 1px solid var(--line); background: var(--paper);
}
#atfa-expo27 .afpx-chips { display: flex; flex-wrap: wrap; gap: 6px; }
#atfa-expo27 .afpx-chip {
  display: inline-flex; align-items: center; gap: 7px;
