  cursor: pointer; white-space: nowrap;
  transition: background-color .15s, border-color .15s, color .15s;
}
@media (hover: hover) {
  #atfa-expo27 .afpx-chip:hover { border-color: var(--brand); color: var(--brand); background: #fff; }
}
#atfa-expo27 .afpx-chip[aria-pressed="true"],
