#atfa-expo27 .afpx-sw { width: 10px; height: 10px; border-radius: 2px; border: 1px solid; flex: none; }

#atfa-expo27 .afpx-zoom { display: flex; gap: 4px; margin-left: auto; }
#atfa-expo27 .afpx-zbtn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 34px; height: 32px; padding: 0;
