@media (hover: hover) {
  #atfa-expo27 .afpx-zbtn:hover { border-color: var(--brand); color: var(--brand); background: #fff; }
}
#atfa-expo27 .afpx-zbtn.afpx-zreset { width: auto; padding: 0 12px; font-size: 13px; }

#atfa-expo27 .afpx-chip:focus-visible,
#atfa-expo27 .afpx-zbtn:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }

/* Plan */
#atfa-expo27 .afpx-stage {
  position: relative;
  width: 100%;
  max-height: min(78vh, 860px);
  min-height: 260px;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(0,0,0,.024) 1px, transparent 1px) 0 0 / 24px 24px,
    linear-gradient(rgba(0,0,0,.024) 1px, transparent 1px) 0 0 / 24px 24px,
    var(--paper);
  touch-action: pan-x pan-y;
  cursor: grab;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
#atfa-expo27 .afpx-stage.is-drag { cursor: grabbing; }
#atfa-expo27 .afpx-svg { display: block; width: 100%; height: 100%; }

#atfa-expo27 .afpx-stand { cursor: pointer; outline: none; }
#atfa-expo27 .afpx-stand text { pointer-events: none; }
#atfa-expo27 .afpx-lbl { fill: var(--ink); }
#atfa-expo27 .afpx-sub { fill: #4F5D57; }
#atfa-expo27 .afpx-stand.is-sold .afpx-lbl,
#atfa-expo27 .afpx-stand.is-sold .afpx-sub { fill: #fff; }
#atfa-expo27 .afpx-stand.is-hold .afpx-sub { fill: #7A5310; }
#atfa-expo27 .afpx-stand.is-loading rect,
#atfa-expo27 .afpx-stand.is-unknown rect { stroke-dasharray: .5 .35; }
@media (hover: hover) {
  #atfa-expo27 .afpx-stand:hover rect { filter: brightness(.94); }
}
#atfa-expo27 .afpx-stand.is-sel rect { stroke: #111; stroke-width: .42; }
#atfa-expo27 .afpx-stand:focus-visible rect { stroke: #111; stroke-width: .55; }
#atfa-expo27 .afpx-stand.is-dim { opacity: .18; }

#atfa-expo27 .afpx-north {
  position: absolute; top: 10px; left: 10px; z-index: 2;
