#atfa-expo27 .afpx-tip span { display: block; }
#atfa-expo27 .afpx-tip .afpx-tip-st { color: #FFC178; font-weight: 700; }

#atfa-expo27 .afpx-hint {
  position: absolute; left: 50%; bottom: 14px; z-index: 6;
  transform: translateX(-50%);
