  background: rgba(22,33,28,.9); color: #fff;
  font-size: 13px; line-height: 1.3; text-align: center;
  pointer-events: none; opacity: 0; transition: opacity .2s;
}
#atfa-expo27 .afpx-hint.is-on { opacity: 1; }

#atfa-expo27 .afpx-noscript { padding: 24px; font-size: 14px; }
#atfa-expo27 .afpx-noscript a { color: var(--brand); text-decoration: underline; }

/* Legend */
#atfa-expo27 .afpx-legend {
  display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center;
  padding: 10px 16px; border-top: 1px solid var(--line); background: var(--paper);
  font-size: 12px; color: var(--muted);
}
#atfa-expo27 .afpx-legend ul { display: flex; flex-wrap: wrap; gap: 6px 14px; }
