#atfa-expo27 .afpx-legend i { width: 12px; height: 12px; border-radius: 3px; border: 1px solid; display: inline-block; }
#atfa-expo27 .afpx-legend i.is-wall { width: 16px; height: 0; border: 0; border-top: 3px solid #16211C; border-radius: 0; }
#atfa-expo27 .afpx-legend i.is-route { width: 16px; background: #E7ECEA; border-color: #C9D1CD; border-style: dashed; }
#atfa-expo27 .afpx-help { margin-left: auto; }

/* Side panel */
#atfa-expo27 .afpx-side { position: relative; min-width: 0; background: var(--paper); border-left: 1px solid var(--line); }
