#atfa-expo27 .afpx-count { margin-top: 8px; font-size: 12px; color: var(--muted); }

#atfa-expo27 .afpx-list { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; }
#atfa-expo27 .afpx-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 9px 14px; border: 0; border-bottom: 1px solid #EEF1F0; border-radius: 0;
