  font-size: 13px; font-weight: 400; line-height: 1.3; cursor: pointer;
}
@media (hover: hover) {
  #atfa-expo27 .afpx-item:hover { background: var(--brand-lt); color: var(--ink); }
}
#atfa-expo27 .afpx-item.is-sel { background: var(--brand-lt); box-shadow: inset 3px 0 0 var(--brand); }
#atfa-expo27 .afpx-item:focus-visible { outline: 2px solid var(--brand); outline-offset: -2px; }
#atfa-expo27 .afpx-dot { width: 9px; height: 9px; border-radius: 50%; flex: none; }
