#atfa-expo27 .afpx-mt { display: block; font-size: 11.5px; color: var(--muted); }
#atfa-expo27 .afpx-pr { font-weight: 700; color: var(--brand); white-space: nowrap; }
#atfa-expo27 .afpx-pr.is-hold { color: #9A6A12; }
#atfa-expo27 .afpx-pr.is-sold { color: var(--muted); }
#atfa-expo27 .afpx-empty { padding: 26px 14px; text-align: center; color: var(--muted); }

#atfa-expo27 .afpx-sr {
  position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* Buttons (shared with the popup) */
#atfa-expo27 .afpx-btn,
#atfa-expo27-modal .afpx-btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 42px; padding: 0 18px; border: 1px solid var(--brand); border-radius: 10px;
  background: var(--brand); color: #fff;
  font-size: 14px; font-weight: 600; line-height: 1.2; text-decoration: none; cursor: pointer;
}
#atfa-expo27 .afpx-btn.is-ghost, #atfa-expo27-modal .afpx-btn.is-ghost { background: #fff; color: var(--brand); }
@media (hover: hover) {
  #atfa-expo27 .afpx-btn:hover, #atfa-expo27-modal .afpx-btn:hover { background: var(--brand-dk); border-color: var(--brand-dk); color: #fff; }
  #atfa-expo27 .afpx-btn.is-ghost:hover, #atfa-expo27-modal .afpx-btn.is-ghost:hover { background: var(--brand-lt); color: var(--brand-dk); }
}
#atfa-expo27 .afpx-btn:active, #atfa-expo27-modal .afpx-btn:active { background: var(--brand-dk); border-color: var(--brand-dk); color: #fff; }
#atfa-expo27 .afpx-btn.is-ghost:active, #atfa-expo27-modal .afpx-btn.is-ghost:active { background: var(--brand-lt); color: var(--brand-dk); }
#atfa-expo27 .afpx-btn.is-small { min-height: 30px; padding: 0 12px; font-size: 12.5px; border-radius: 8px; }
#atfa-expo27 .afpx-btn:focus-visible, #atfa-expo27-modal .afpx-btn:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }

/* Popup */
#atfa-expo27-modal {
  position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 2147483000;
  display: flex; align-items: center; justify-content: center; padding: 20px;
}
#atfa-expo27-modal[hidden] { display: none !important; }
#atfa-expo27-modal .afpx-modal-bd {
  position: absolute; top: 0; right: 0; bottom: 0; left: 0; background: rgba(12,14,16,.55);
  touch-action: none;
}
#atfa-expo27-modal .afpx-modal-card {
  position: relative; width: 100%; max-width: 520px;
  max-height: calc(100vh - 40px); max-height: calc(100dvh - 40px);
  overflow: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch;
  background: #fff; color: var(--ink); border-radius: 16px;
  box-shadow: 0 24px 70px rgba(0,0,0,.35); outline: none;
  animation: afpxPop .16s ease-out;
}
@keyframes afpxPop { from { opacity: 0; transform: translateY(8px) scale(.985); } to { opacity: 1; transform: none; } }
#atfa-expo27-modal .afpx-x {
  position: absolute; top: 12px; right: 12px;
  display: flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; padding: 0; border: 0; border-radius: 50%;
  background: #EFF1F0; color: var(--muted); font-size: 22px; line-height: 1; cursor: pointer;
}
@media (hover: hover) {
  #atfa-expo27-modal .afpx-x:hover { background: #E2E6E4; color: var(--ink); }
}
#atfa-expo27-modal .afpx-x:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }
#atfa-expo27-modal .afpx-mhead { padding: 22px 60px 14px 22px; border-bottom: 1px solid var(--line); }
#atfa-expo27-modal .afpx-badge {
  display: inline-block; padding: 3px 9px; border-radius: 999px;
  background: #8A958F; color: #fff;
  font-size: 11px; font-weight: 700; letter-spacing: .6px; text-transform: uppercase;
}
#atfa-expo27-modal .afpx-badge.is-available { background: var(--avail); }
#atfa-expo27-modal .afpx-badge.is-hold { background: var(--hold); }
#atfa-expo27-modal .afpx-badge.is-sold { background: #6E7B75; }
#atfa-expo27-modal h2 { margin: 10px 0 3px; font-size: 22px; font-weight: 700; color: var(--ink); overflow-wrap: anywhere; }
#atfa-expo27-modal .afpx-meta { font-size: 13px; color: var(--muted); }
#atfa-expo27-modal .afpx-open { margin-top: 2px; font-size: 13px; font-weight: 600; color: #3F4C46; }
#atfa-expo27-modal .afpx-mbody { padding: 16px 22px 4px; }
#atfa-expo27-modal .afpx-mbody p { margin: 0 0 12px; font-size: 14.5px; line-height: 1.55; }
#atfa-expo27-modal .afpx-bio { white-space: pre-line; overflow-wrap: anywhere; }
#atfa-expo27-modal .afpx-muted { color: var(--muted); }
#atfa-expo27-modal .afpx-mbody .afpx-price { margin: 0 0 4px; font-size: 30px; font-weight: 800; line-height: 1.1; color: var(--brand); }
#atfa-expo27-modal .afpx-mbody .afpx-price-note { font-size: 12.5px; color: var(--muted); }
#atfa-expo27-modal .afpx-mbody .afpx-warn {
  padding: 9px 11px; border-radius: 9px; background: #FFF7E6; border: 1px solid #F2D49A; color: #6B4B12; font-size: 13px;
}
#atfa-expo27-modal .afpx-mfoot { display: flex; flex-wrap: wrap; gap: 10px 14px; align-items: center; padding: 8px 22px 22px; }
#atfa-expo27-modal .afpx-alt { flex-basis: 100%; margin: 0; font-size: 13px; color: var(--muted); }
#atfa-expo27-modal .afpx-alt a { color: var(--brand); text-decoration: underline; }
#atfa-expo27-modal .afpx-site { font-size: 12.5px; color: var(--muted); overflow-wrap: anywhere; }
#atfa-expo27-modal .afpx-mfoot .afpx-btn.is-ghost { margin-left: auto; }

/* Phones: popup slides up from the bottom and can be dragged down to close */
@media (max-width: 600px) {
  #atfa-expo27-modal { align-items: flex-end; padding: 0; }
  #atfa-expo27-modal .afpx-modal-card {
    max-width: none; max-height: 88vh; max-height: 88dvh; border-radius: 18px 18px 0 0;
    padding-bottom: env(safe-area-inset-bottom);
    animation: afpxUp .2s ease-out;
  }
  #atfa-expo27-modal .afpx-modal-card::before {
    content: ""; position: absolute; top: 7px; left: 50%; width: 38px; height: 4px;
    margin-left: -19px; border-radius: 4px; background: #D3D9D6;
  }
  #atfa-expo27-modal .afpx-mhead { padding-top: 24px; }
  #atfa-expo27-modal .afpx-mfoot .afpx-btn { flex: 1 1 100%; min-height: 46px; }
  #atfa-expo27-modal .afpx-mfoot .afpx-btn.is-ghost { margin-left: 0; }
  #atfa-expo27-modal .afpx-x { width: 40px; height: 40px; top: 14px; right: 12px; }
}
@keyframes afpxUp { from { transform: translateY(24px); opacity: .6; } to { transform: none; opacity: 1; } }

/* Touch screens: bigger targets, and 16px text in the search box so iPhones
   don't zoom the page when it's tapped. */
@media (pointer: coarse) {
  #atfa-expo27 .afpx-chip { height: 38px; }
  #atfa-expo27 .afpx-zbtn { width: 40px; height: 38px; }
  #atfa-expo27 .afpx-search input { height: 44px; font-size: 16px; }
  #atfa-expo27 .afpx-item { padding-top: 11px; padding-bottom: 11px; }
  #atfa-expo27-modal .afpx-x { width: 40px; height: 40px; }
  #atfa-expo27 .afpx-staff .afpx-btn.is-small { min-height: 42px; font-size: 13.5px; }
}

/* Phones: staff buttons share a full-width row under the text */
@media (max-width: 600px) {
  #atfa-expo27 .afpx-staff-btns { flex: 1 1 100%; }
  #atfa-expo27 .afpx-staff-btns .afpx-btn { flex: 1 1 auto; }
}

/* Narrower containers: list below the plan, no scrolling box inside the page */
@container afpx (max-width: 900px) {
  #atfa-expo27 .afpx-body { grid-template-columns: minmax(0, 1fr); }
  #atfa-expo27 .afpx-side { border-left: 0; border-top: 1px solid var(--line); }
  #atfa-expo27 .afpx-side-in { position: static; }
  #atfa-expo27 .afpx-list {
    max-height: none; overflow: visible;
    display: grid; grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
  }
  #atfa-expo27 .afpx-list .afpx-empty { grid-column: 1 / -1; }
  #atfa-expo27 .afpx-stage { max-height: 72vh; }
}
@container afpx (max-width: 600px) {
  #atfa-expo27 .afpx-top { padding: 14px; gap: 10px; }
  #atfa-expo27 .afpx-top h1 { font-size: 17px; }
  #atfa-expo27 .afpx-top p { font-size: 12px; }
  #atfa-expo27 .afpx-stats { gap: 16px; }
  #atfa-expo27 .afpx-stats dd { font-size: 18px; }
  #atfa-expo27 .afpx-stats div { align-items: flex-start; }
  /* One row: the filter chips scroll sideways, zoom buttons stay put */
  #atfa-expo27 .afpx-toolbar { padding: 8px 10px; flex-wrap: nowrap; }
  #atfa-expo27 .afpx-chips {
    gap: 5px; flex: 1 1 auto; min-width: 0; flex-wrap: nowrap;
    overflow-x: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch;
    -webkit-mask-image: linear-gradient(90deg, #000 85%, transparent);
    mask-image: linear-gradient(90deg, #000 85%, transparent);
    padding-right: 18px;
  }
  #atfa-expo27 .afpx-chips::-webkit-scrollbar { display: none; }
  #atfa-expo27 .afpx-chip { flex: none; padding: 0 11px; font-size: 12.5px; }
  #atfa-expo27 .afpx-zoom { margin-left: 0; flex: none; }
  #atfa-expo27 .afpx-zbtn.afpx-zreset { padding: 0 9px; font-size: 12px; }
  #atfa-expo27 .afpx-legend { padding: 10px 12px; font-size: 11.5px; }
  #atfa-expo27 .afpx-help { margin-left: 0; flex-basis: 100%; }
  #atfa-expo27 .afpx-list { grid-template-columns: minmax(0, 1fr); }
  /* The plan is cropped closer on phones, so the north arrow moves to the empty
     bottom-left corner instead of covering the main entrance. */
  #atfa-expo27 .afpx-north { top: auto; bottom: 8px; left: 8px; width: 28px; height: 36px; font-size: 10px; }
  #atfa-expo27 .afpx-north svg { width: 22px; height: 22px; }
}

/* Browsers without container queries (older iPhones): same layout by screen width */
@supports not (container-type: inline-size) {
  @media (max-width: 960px) {
    #atfa-expo27 .afpx-body { grid-template-columns: minmax(0, 1fr); }
    #atfa-expo27 .afpx-side { border-left: 0; border-top: 1px solid var(--line); }
    #atfa-expo27 .afpx-side-in { position: static; }
    #atfa-expo27 .afpx-list { max-height: none; overflow: visible; }
    #atfa-expo27 .afpx-stage { max-height: 72vh; }
  }
  @media (max-width: 640px) {
    #atfa-expo27 .afpx-top { padding: 14px; gap: 10px; }
    #atfa-expo27 .afpx-top h1 { font-size: 17px; }
    #atfa-expo27 .afpx-toolbar { padding: 8px 10px; }
    #atfa-expo27 .afpx-zoom { margin-left: 0; }
    #atfa-expo27 .afpx-help { margin-left: 0; flex-basis: 100%; }
  }
}

@media (prefers-reduced-motion: reduce) {
  #atfa-expo27 *, #atfa-expo27-modal * { transition: none !important; animation: none !important; }
}

/* Phones held sideways: let the plan use most of the screen height */
@media (max-height: 500px) and (pointer: coarse) {
  #atfa-expo27 .afpx-stage { max-height: 86vh; }
}

