  sv('path', { d: P.outer, fill: '#F5F1E8' }, deco);
  sv('path', { d: GEO.radial, fill: 'none', stroke: '#D9CDB4', 'stroke-width': 0.22, 'stroke-dasharray': '1.6 1.1' }, deco);
  sv('path', { d: P.hall, fill: 'url(#afpxHatch)' }, deco);
