    var sub = svText(g, cx, 0, '', { 'class': 'afpx-sub', 'text-anchor': 'middle', 'font-size': s.fs, 'font-weight': 500 });
    NODES[s.id] = { g: g, rect: rect, lbl: lbl, sub: sub };
  });

  // Labels: the stand number plus small print (size, "On hold" or the company)
